// Generate a static worker from the same tested routing engine; no runtime eval.
const fs=require('node:fs'),path=require('node:path');
const source=fs.readFileSync(path.join(__dirname,'../dist/app.js'),'utf8').split('bind();updateGridSnap();')[0];
fs.writeFileSync(path.join(__dirname,'../dist/routing-worker.js'),
  "// Generated by scripts/build-routing-worker.cjs\nconst document={getElementById:()=>({})},localStorage={getItem:()=>null};\n"+source+
  `\nself.onmessage=event=>{try{model=event.data.model||event.data;const ids=event.data.wireIds;const result=planTidyBestEffort(ids?new Set(ids):null);self.postMessage({result});}catch(error){self.postMessage({error:error.message,code:error.code});}};\n`);
